\centering
\includegraphics[width=\columnwidth]{figures/fig4_prolog_comparison.pdf}
\caption{Prolog exec-only ISR across three seeds. ISR$^*$ is near-zero for all seeds (s42${=}$0.037, s43${=}$0.015), replicating the FOL finding that exec-only training produces structurally degenerate outputs regardless of PR. Seed~44 ISR$^*{=}$0.387 is a small-sample artifact ($n{=}$21 proved). Cross-seed PR instability ($\sigma{=}$31pp) also replicates.}
\label{fig:prolog-comparison}
\end{figure}

